403:     let method = msg.get("method").and_then(Value::as_str)?;
404:     if method.starts_with("notifications/") {
405:         return None;
406:     }
407:     let params = msg.get("params").cloned().unwrap_or(Value::Null);
408:     let state = ctx.app.state::<AppState>();
409:     if method != "ping" {
410:         let label = if method == "tools/call" {
411:             let n = params.get("name").and_then(Value::as_str).unwrap_or("?");
412:             format!("tools/call {n}")
413:         } else {
414:             method.to_string()
415:         };
416:         state.bridge.hit(label);
417:     }
418:     let id = msg.get("id").cloned()?;
419: 
420:     let out: Result<Value, (i64, String)> = match method {
421:         "initialize" => Ok(initialize_result(&params)),
422:         "ping" => Ok(json!({})),
423:         "tools/list" => Ok(json!({ "tools": list_tools(ctx).await })),
424:         "tools/call" => call_tool(ctx, &params).await,
425:         _ => Err((-32601, format!("méthode non gérée : {method}"))),
426:     };
427:     Some(match out {
428:         Ok(r) => json!({ "jsonrpc": "2.0", "id": id, "result": r }),
429:         Err((code, m)) => {
430:             json!({ "jsonrpc": "2.0", "id": id, "error": { "code": code, "message": m } })
431:         }
432:     })
433: }
