457:             [(header::WWW_AUTHENTICATE, "Bearer")],
458:             "unauthorized",
459:         )
460:             .into_response();
461:     }
462:     let Ok(msg) = serde_json::from_slice::<Value>(&body) else {
463:         return json_response(
464:             StatusCode::BAD_REQUEST,
465:             &json!({ "jsonrpc": "2.0", "id": null,
466:                      "error": { "code": -32700, "message": "JSON invalide" } }),
467:         );
468:     };
469:     if let Some(batch) = msg.as_array() {
470:         let mut out = Vec::new();
471:         for m in batch {
472:             if let Some(r) = handle_rpc(&ctx, m).await {
473:                 out.push(r);
474:             }
475:         }
476:         if out.is_empty() {
477:             return StatusCode::ACCEPTED.into_response();
478:         }
479:         return json_response(StatusCode::OK, &Value::Array(out));
480:     }
