228: fn percent_encode(input: &str) -> String {
229:     let mut out = String::with_capacity(input.len());
230:     for byte in input.as_bytes() {
231:         match *byte {
232:             b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
