243: fn build_multipart_file(
244:     field_name: &str,
245:     filename: &str,
246:     content_type: &str,
247:     bytes: &[u8],
248: ) -> (String, Vec<u8>) {
249:     let nanos = SystemTime::now()
250:         .duration_since(UNIX_EPOCH)
251:         .map(|d| d.as_nanos())
252:         .unwrap_or(0);
253:     let seq = BOUNDARY_COUNTER.fetch_add(1, Ordering::Relaxed);
254:     let boundary = format!("----fsdesktop{nanos:x}{seq:x}");
255:     let safe_field = sanitize_header_value(field_name);
256:     let safe_name = sanitize_header_value(filename);
257:     let safe_ct = if content_type.trim().is_empty() {
258:         "application/octet-stream".to_string()
259:     } else {
260:         sanitize_header_value(content_type)
261:     };
262: 
263:     let head = format!(
264:         "--{boundary}\r\n\
265:          Content-Disposition: form-data; name=\"{safe_field}\"; filename=\"{safe_name}\"\r\n\
266:          Content-Type: {safe_ct}\r\n\r\n"
267:     );
268:     let tail = format!("\r\n--{boundary}--\r\n");
269: 
270:     let mut body = Vec::with_capacity(head.len() + bytes.len() + tail.len());
271:     body.extend_from_slice(head.as_bytes());
272:     body.extend_from_slice(bytes);
273:     body.extend_from_slice(tail.as_bytes());
274:     (format!("multipart/form-data; boundary={boundary}"), body)
275: }
