//! Types publics de la boucle d'agent : requête, état persisté, événements.

use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use fs_api::StreamOptions;
use serde::{Deserialize, Serialize};
use serde_json::Value;

pub const RUN_STATE_VERSION: u32 = 1;

/// Demande de lancement d'un run.
#[derive(Debug, Clone)]
pub struct RunRequest {
    pub run_id: String,
    pub chat_id: Option<String>,
    pub agent_id: i64,
    /// Texte exact saisi par l'utilisateur : jamais modifié par l'application.
    pub content: String,
    pub workdir: Option<PathBuf>,
    pub auto_accept: bool,
    pub eco: bool,
    pub options: StreamOptions,
}

/// État d'un run. Toute transition est persistée avant l'action suivante.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RunStatus {
    Preparing,
    Streaming,
    AwaitingTools,
    Executing,
    SendingResults,
    Resuming,
    Done,
    Failed,
    Cancelled,
    Abandoned,
}

impl RunStatus {
    pub fn is_terminal(self) -> bool {
        matches!(
            self,
            RunStatus::Done | RunStatus::Failed | RunStatus::Cancelled | RunStatus::Abandoned
        )
    }
}

/// Décision prise pour un appel d'outil.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Decision {
    Allowed,
    Denied,
    Unknown,
}

/// Appel d'outil en attente ou exécuté, conservé pour la reprise.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PendingCall {
    pub call_id: String,
    pub name: String,
    pub arguments: Value,
    #[serde(default)]
    pub decision: Option<Decision>,
    #[serde(default)]
    pub executed_at: Option<String>,
    #[serde(default)]
    pub output: Option<String>,
    #[serde(default)]
    pub is_error: bool,
    #[serde(default)]
    pub denied: bool,
}

impl PendingCall {
    pub fn new(call_id: String, name: String, arguments: Value) -> Self {
        Self {
            call_id,
            name,
            arguments,
            decision: None,
            executed_at: None,
            output: None,
            is_error: false,
            denied: false,
        }
    }
}

/// Compteurs cumulés d'un run.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct Usage {
    pub api_calls: u32,
    pub prompt_tokens: u64,
    pub output_tokens: u64,
}

/// État complet persisté dans `<config>/runs/<run_id>.json`.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RunState {
    pub version: u32,
    pub run_id: String,
    #[serde(default)]
    pub chat_id: Option<String>,
    pub agent_id: i64,
    pub created_at: String,
    pub updated_at: String,
    pub status: RunStatus,
    #[serde(default)]
    pub step: u32,
    #[serde(default)]
    pub last_event_id: Option<String>,
    pub user_content: String,
    #[serde(default)]
    pub workdir: Option<String>,
    #[serde(default)]
    pub pending_calls: Vec<PendingCall>,
    #[serde(default)]
    pub results_sent: bool,
    #[serde(default)]
    pub usage: Usage,
}

impl RunState {
    pub fn new(req: &RunRequest, now: String) -> Self {
        Self {
            version: RUN_STATE_VERSION,
            run_id: req.run_id.clone(),
            chat_id: req.chat_id.clone(),
            agent_id: req.agent_id,
            created_at: now.clone(),
            updated_at: now,
            status: RunStatus::Preparing,
            step: 0,
            last_event_id: None,
            user_content: req.content.clone(),
            workdir: req.workdir.as_ref().map(|p| p.display().to_string()),
            pending_calls: Vec::new(),
            results_sent: false,
            usage: Usage::default(),
        }
    }

    pub fn touch(&mut self) {
        self.updated_at = now_iso();
    }
}

/// Origine d'un appel d'outil.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Origin {
    /// Outil local du catalogue `client-tools`.
    Local,
    /// Outil de plateforme (`mcp__…`) : jamais exécuté par la boucle client.
    Mcp,
}

/// Événements émis vers l'interface. Aucun ne contient d'instruction pour le modèle.
#[derive(Debug, Clone)]
pub enum AgentEvent {
    Opened { chat_id: String },
    Title { chat_id: String, title: String },
    Delta { text: String },
    Reasoning { text: String },
    ToolCall {
        call_id: String,
        name: String,
        origin: Origin,
        args: Value,
        needs_confirm: bool,
    },
    ToolResult {
        call_id: String,
        output: String,
        is_error: bool,
        denied: bool,
    },
    Notice { text: String },
    AwaitingTools { run_id: String, calls: usize },
    Resumed { run_id: String },
    RunInterrupted { run_id: String, reason: String },
    Done {
        chat_id: String,
        message_id: String,
        prompt_tokens: Option<u64>,
        output_tokens: Option<u64>,
        total_prompt_tokens: u64,
        total_output_tokens: u64,
        api_calls: u32,
        eco: bool,
    },
    Failed {
        code: String,
        message: String,
        retryable: bool,
    },
    Cancelled,
}

/// Drapeau d'annulation partagé entre la commande Tauri et la boucle.
#[derive(Clone, Default)]
pub struct RunControl {
    flag: Arc<AtomicBool>,
}

impl RunControl {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_flag(flag: Arc<AtomicBool>) -> Self {
        Self { flag }
    }

    pub fn flag(&self) -> Arc<AtomicBool> {
        self.flag.clone()
    }

    pub fn cancel(&self) {
        self.flag.store(true, Ordering::SeqCst);
    }

    pub fn is_cancelled(&self) -> bool {
        self.flag.load(Ordering::SeqCst)
    }
}

/// Horodatage ISO-8601 UTC, seconde près.
pub fn now_iso() -> String {
    chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
}

//! Abstraction du transport : un « tour » de conversation (démarrage, résultats
//! d'outils ou reprise de flux). L'implémentation HTTP vit dans l'application.

use async_trait::async_trait;
use fs_api::{StreamOptions, ToolCall, ToolResult};

use crate::model::AgentEvent;

/// Récepteur d'événements. `false` = l'appelant a annulé : l'implémentation peut
/// cesser d'émettre, mais doit terminer proprement.
pub trait EventSink {
    fn emit(&mut self, event: AgentEvent) -> bool;
}

impl<F> EventSink for F
where
    F: FnMut(AgentEvent) -> bool,
{
    fn emit(&mut self, event: AgentEvent) -> bool {
        self(event)
    }
}

/// Ce qu'il faut envoyer au serveur pour ce tour.
#[derive(Debug, Clone)]
pub enum TurnInput {
    /// Premier tour d'un run : crée le chat si `chat_id` est absent.
    Start {
        chat_id: Option<String>,
        agent_id: i64,
        content: String,
        tools: Vec<String>,
        options: StreamOptions,
    },
    /// Renvoi des résultats du tour d'outils précédent.
    Results {
        chat_id: String,
        results: Vec<ToolResult>,
        options: StreamOptions,
    },
    /// Ré-attachement au flux d'une génération en cours.
    Resume {
        chat_id: String,
        last_event_id: Option<String>,
    },
}

/// Fin logique d'un tour.
#[derive(Debug, Clone)]
pub enum Terminal {
    Completed,
    Cancelled,
    Failed {
        code: String,
        message: String,
        retryable: bool,
    },
}

/// Résultat agrégé d'un tour, en plus des événements déjà émis.
#[derive(Debug, Clone)]
pub struct TurnOutcome {
    pub chat_id: Option<String>,
    pub message_id: Option<String>,
    pub content: String,
    pub tool_calls: Vec<ToolCall>,
    pub prompt_tokens: Option<u64>,
    pub output_tokens: Option<u64>,
    pub terminal: Terminal,
    pub last_event_id: Option<String>,
}

/// Erreur de transport ou de protocole HTTP.
#[derive(Debug, thiserror::Error)]
pub enum BackendError {
    #[error("HTTP {status} : {body}")]
    Status { status: u16, body: String },
    #[error("réseau : {0}")]
    Transport(String),
    #[error("flux SSE : {0}")]
    Stream(String),
    #[error("{0}")]
    Unsupported(String),
    #[error("{0}")]
    Other(String),
}

impl BackendError {
    /// Une reprise de flux est-elle pertinente ?
    pub fn retryable(&self) -> bool {
        match self {
            BackendError::Transport(_) | BackendError::Stream(_) => true,
            BackendError::Status { status, .. } => matches!(status, 408 | 425 | 500..=599),
            BackendError::Unsupported(_) | BackendError::Other(_) => false,
        }
    }

    pub fn status(&self) -> Option<u16> {
        match self {
            BackendError::Status { status, .. } => Some(*status),
            _ => None,
        }
    }
}

/// Vue minimale d'un chat pour réconcilier un run interrompu.
#[derive(Debug, Clone, Default)]
pub struct ChatSnapshot {
    pub pending_tool_calls: Vec<ToolCall>,
    pub last_event_id: Option<String>,
}

/// Transport de conversation.
#[async_trait]
pub trait ChatBackend: Send + Sync {
    async fn turn(
        &self,
        input: &TurnInput,
        sink: &mut dyn EventSink,
    ) -> Result<TurnOutcome, BackendError>;

    async fn cancel(&self, chat_id: &str) -> Result<(), BackendError> {
        let _ = chat_id;
        Ok(())
    }

    async fn fetch_chat(&self, chat_id: &str) -> Result<ChatSnapshot, BackendError> {
        let _ = chat_id;
        Ok(ChatSnapshot::default())
    }
}

//! Catalogue et exécution des outils locaux.

use std::path::PathBuf;

use async_trait::async_trait;
use fs_api::ToolCall;
use serde_json::Value;

/// Niveau de risque d'un outil.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Risk {
    /// Lecture seule : jamais de confirmation.
    ReadOnly,
    /// Modifie des fichiers : confirmation selon le mode.
    Mutating,
    /// Exécute une commande : confirmation selon le mode.
    Command,
}

/// Description d'un outil local.
#[derive(Debug, Clone)]
pub struct ToolSpec {
    pub name: String,
    pub risk: Risk,
}

impl ToolSpec {
    pub fn new(name: impl Into<String>, risk: Risk) -> Self {
        Self {
            name: name.into(),
            risk,
        }
    }
}

/// Résultat d'exécution d'un outil.
#[derive(Debug, Clone, Default)]
pub struct ToolExecution {
    pub output: String,
    pub is_error: bool,
    /// Information à afficher dans l'interface (journal des modifications).
    pub notice: Option<String>,
}

impl ToolExecution {
    pub fn ok(output: impl Into<String>) -> Self {
        Self {
            output: output.into(),
            is_error: false,
            notice: None,
        }
    }

    pub fn error(message: impl Into<String>) -> Self {
        Self {
            output: message.into(),
            is_error: true,
            notice: None,
        }
    }
}

/// Contexte d'exécution.
#[derive(Debug, Clone)]
pub struct ToolContext {
    pub run_id: String,
    pub call_id: String,
    pub workdir: Option<PathBuf>,
}

/// Exécuteur d'outils locaux.
#[async_trait]
pub trait ToolExecutor: Send + Sync {
    /// `None` = nom hors catalogue : la boucle répond `isError: true`.
    fn spec(&self, name: &str) -> Option<ToolSpec>;

    async fn execute(&self, call: &ToolCall, ctx: &ToolContext) -> ToolExecution;
}

/// Arguments d'un appel : objet JSON ou chaîne JSON selon le fournisseur.
pub fn parse_arguments(raw: &Value) -> Value {
    match raw {
        Value::String(s) => serde_json::from_str(s).unwrap_or(Value::Null),
        other => other.clone(),
    }
}

//! Décision d'autorisation avant l'exécution d'un outil.

use std::path::PathBuf;

use async_trait::async_trait;
use serde_json::Value;

use crate::tools::Risk;

/// Demande soumise à l'approbateur.
#[derive(Debug, Clone)]
pub struct ApprovalRequest {
    pub run_id: String,
    pub call_id: String,
    pub name: String,
    pub args: Value,
    pub workdir: Option<PathBuf>,
    pub auto_accept: bool,
    pub risk: Risk,
}

/// Décision de l'approbateur.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Approval {
    /// Exécuter sans demander.
    Allow,
    /// Demander à l'utilisateur.
    Ask,
    /// Refuser avec un message renvoyé au modèle.
    Deny(String),
}

/// Politique d'approbation : les modes de l'application vivent dans l'implémentation.
#[async_trait]
pub trait Approver: Send + Sync {
    async fn decide(&self, request: &ApprovalRequest) -> Approval;

    /// Appelé seulement si `decide` a renvoyé `Ask`.
    async fn confirm(&self, request: &ApprovalRequest) -> bool;
}

/// Approuve tout (tests, automatisation explicite).
pub struct ApproveAll;

#[async_trait]
impl Approver for ApproveAll {
    async fn decide(&self, _request: &ApprovalRequest) -> Approval {
        Approval::Allow
    }

    async fn confirm(&self, _request: &ApprovalRequest) -> bool {
        true
    }
}

/// Refuse tout (tests, mode strict).
pub struct DenyAll;

#[async_trait]
impl Approver for DenyAll {
    async fn decide(&self, _request: &ApprovalRequest) -> Approval {
        Approval::Deny("Refusé.".to_string())
    }

    async fn confirm(&self, _request: &ApprovalRequest) -> bool {
        false
    }
}

//! Limites et seuils d'un run.

/// Limite de résultats imposée par `client-tools.md`.
pub const MAX_RESULTS_PER_TURN: usize = 32;
/// Limite de caractères d'une sortie d'outil.
pub const MAX_OUTPUT_CHARS: usize = 40_000;
/// Limite cumulée d'un envoi de résultats.
pub const MAX_RESULTS_CHARS: usize = 120_000;

/// Politique appliquée par la boucle.
#[derive(Debug, Clone)]
pub struct LoopPolicy {
    /// Nombre maximal de tours d'outils pour un message utilisateur.
    pub max_steps: u32,
    pub max_results_per_turn: usize,
    pub max_output_chars: usize,
    pub max_results_chars: usize,
    /// Confirmer aussi les outils en lecture seule (désactivé pour les outils locaux).
    pub confirm_read_only: bool,
    pub eco: bool,
}

impl Default for LoopPolicy {
    fn default() -> Self {
        Self {
            max_steps: 30,
            max_results_per_turn: MAX_RESULTS_PER_TURN,
            max_output_chars: MAX_OUTPUT_CHARS,
            max_results_chars: MAX_RESULTS_CHARS,
            confirm_read_only: false,
            eco: false,
        }
    }
}

impl LoopPolicy {
    pub fn eco() -> Self {
