pub struct TauriSink<'a> {
  channel: &'a Channel<UiEvent>,
  app: &'a AppHandle,
  workdir: Option<PathBuf>,
  control: RunControl,
  calls: HashMap<String, (String, Value)>,
}
impl TauriSink { fn new(...) }
impl EventSink for TauriSink<'_> {
  fn emit(&mut self, ev: AgentEvent) -> bool {
     match ev {
       ToolCall{call_id,name,origin,args,needs_confirm} => {
          self.calls.insert(call_id.clone(),(name.clone(),args.clone()));
          let _ = self.channel.send(UiEvent::ToolCall{ call_id, name, origin: match origin {Origin::Mcp=>"mcp",_=>"local"}.into(), args: display_args(&args), needs_confirm});
       }
       ToolResult{call_id,output,is_error,denied} => {
          // changelog + terminal
          if let Some((name,args)) = self.calls.remove(&call_id) {
             if let Some(cmd) = ... run_command { term::emit_ai(...) }
             if let Some(label)=changelog::label(&name,&args,None) { status; record; channel Notice }
          }
          let _ = self.channel.send(UiEvent::ToolResult{call_id, output: preview(&output), is_error, denied});
       }
       ...
     }
     !self.control.is_cancelled()
  }
}
```
Need config dir; use `config_dir(self.app).ok()`.

changelog::record signature `(dir, name, label, status, root)`. root workdir as_deref.

term::emit_ai(app, cmd, output, is_error, root). fine.

UiEvent::Reasoning expects `text` field named `text`. Map.

AgentEvent::Done fields match UiEvent::Done names exactly except `eco`. Good.

AgentEvent::Failed fields match.

Notice, Opened, Title, Cancelled.

Resumed/AwaitingTools/RunInterrupted: add UiEvent variants in main.rs. Alternatively map AwaitingTools to Notice. Let's add variants to UiEvent:
```rust
Resumed { run_id },
AwaitingTools { run_id, calls },
RunInterrupted { run_id, reason },
```
No front handling; fine.

`ApiBackend`:
```rust
pub struct ApiBackend { app: AppHandle }

#[async_trait]
impl ChatBackend for ApiBackend {
  async fn turn(&self, input:&TurnInput, sink:&mut dyn EventSink)->Result<TurnOutcome,BackendError> {
    let state = self.app.state::<AppState>();
    let c = client(&self.app,&state).await.map_err(BackendError::Other)?;
    let mut acc = Accum::default();
    let mut dedupe = HashSet::new();
    let mut handler = |ev: ChatEvent| {
       match ev {
         ChatEvent::Opened{chat_id} => { acc.chat_id=Some(chat_id.clone()); sink.emit(AgentEvent::Opened{chat_id}); }
         ChatEvent::Title{chat_id,title} => { sink.emit(...); }
         ChatEvent::Delta(text) => { acc.content.push_str(&text); sink.emit(...); }
         ChatEvent::ReasoningDelta(text) => { sink.emit(Reasoning); }
         ChatEvent::Completed{chat_id,message} => { 
             acc.chat_id=Some(chat_id);
             acc.message_id=Some(message.id.clone());
             if !message.content.is_empty(){acc.content=message.content;}
             acc.calls=message.tool_calls.clone();
             let u=message.token_usage.unwrap_or_default();
             acc.prompt=u.prompt_token_count; acc.output=u.candidates_token_count;
             acc.terminal=Some(Terminal::Completed);
         }
         ChatEvent::Error(e) => { acc.terminal=Some(Terminal::Failed{...}); }
         ChatEvent::Cancelled{..} => { acc.terminal=Some(Terminal::Cancelled); }
         ChatEvent::Mcp(t)|ChatEvent::Notice(t) => { sink.emit(Notice); }
         ChatEvent::Other(ty) => if (ty.contains("mcp")||ty.contains("tool"))&&dedupe.insert(ty.clone()) { sink.emit(Notice{...}); }
       }
    };
    let last_id = match input {
      TurnInput::Start{chat_id,agent_id,content,tools,options} => {
         let tools_json: Vec<Value> = tools.iter().map(|t| json!(t)).collect();
         match chat_id {
            Some(id) => c.send_message_with_options_id(id, content, Some(*agent_id), &tools_json, &[], options, &mut handler).await,
            None => c.stream_chat_with_options_id(*agent_id, content, &tools_json, options, &mut handler).await,
         }
      }
      TurnInput::Results{chat_id,results,options} => c.send_message_with_options_id(chat_id,"",None,&[],results,options,&mut handler).await,
      TurnInput::Resume{chat_id,last_event_id} => c.resume_stream(chat_id,last_event_id.as_deref(),&mut handler).await,
    }.map_err(map_backend_error)?;
    Ok(TurnOutcome{... terminal: acc.terminal.unwrap_or(Terminal::Failed{code:"STREAM_ENDED"...}), last_event_id: last_id.or(acc.last_event_id)})
  }
  async fn cancel(&self, chat_id:&str)->Result<(),BackendError> { ... c.cancel }
  async fn fetch_chat(&self, chat_id:&str)->Result<ChatSnapshot,BackendError> { let v=c.get_chat; parse toolCalls }
}
```
Note `ChatEvent::Completed` `message` is CompletedMessage; token_usage Option<TokenUsage>.

Important: `Start` when `chat_id` Some should use send_message. On resume? Start only initial.

