```rust
fn map_backend_error(e: fs_api::Error) -> BackendError {
 match e {
  Error::Status{status,body}=>BackendError::Status{status,body},
  Error::Http(e)=>BackendError::Transport(e.to_string()),
  Error::Stream(s)=>BackendError::Stream(s),
  Error::Json(e)=>BackendError::Other(e.to_string()),
  Error::BadKey=>BackendError::Other("jeton invalide".into()),
 }
}
```

