pub struct WorkspaceTools { workdir: Option<PathBuf> }
#[async_trait]
impl ToolExecutor for WorkspaceTools {
  fn spec(&self,name)->Option<ToolSpec> {
     if !fs_tools::NAMES.contains(&name){return None;}
     let risk=match fs_tools::risk(name)? { Safe=>ReadOnly, Edit=>Mutating, Command=>Command };
     Some(ToolSpec::new(name,risk))
  }
