/// Messages dédiés + non-réessayables pour les codes connus du serveur.
fn classify_terminal(code: String, message: String, retryable: bool) -> (String, String, bool) {
    let dedicated = match code.as_str() {
        "CHAT_LOCKED" => Some("Ce chat est verrouillé. Déverrouille-le dans France Student."),
        "CHAT_DELETED" => Some("Ce chat a été supprimé : le message ne peut pas être envoyé."),
        "CHAT_ARCHIVED" => Some("Ce chat est archivé. Restaure-le avant de continuer."),
        "CONTENT_POLICY_VIOLATION" => Some("Le serveur a refusé ce contenu (politique de contenu)."),
        "MCP_TOO_MANY_TOOLS" => Some("Trop d'outils MCP activés pour ce chat : désactive-en quelques-uns."),
        "CHAT_BUSY" => Some("Une génération est déjà en cours dans ce chat."),
        "BUDGET_EXHAUSTED" => Some("Budget de chats épuisé : réessaie après la réinitialisation."),
        _ => None,
    };
    match dedicated {
        Some(text) => (code, format!("{text} ({message})"), false),
        None => (code, message, retryable),
    }
}
