fn first_number(value: &Value, keys: &[&str]) -> Option<f64> {
    for key in keys {
        let Some(found) = value.get(*key) else {
            continue;
        };
        if let Some(number) = found.as_f64() {
            return Some(number);
        }
        if let Some(text) = found.as_str() {
            if let Ok(number) = text.trim_end_matches('%').trim().parse::<f64>() {
                return Some(number);
            }
        }
    }
