577: /// Lit stderr de cloudflared jusqu'à l'URL du tunnel, puis continue de vider le tube.
578: async fn read_tunnel_url(mut child: Child) -> Result<(Child, String), String> {
579:     let stderr = child
580:         .stderr
581:         .take()
582:         .ok_or("sortie de cloudflared indisponible")?;
583:     let mut rd = BufReader::new(stderr);
584:     let mut tail: Vec<String> = Vec::new();
585:     let found = timeout(TUNNEL_WAIT, async {
586:         loop {
587:             // Octets bruts : pas de panique sur un texte non UTF-8.
588:             let mut buf = Vec::new();
589:             match rd.read_until(b'\n', &mut buf).await {
590:                 Ok(0) | Err(_) => return None,
591:                 Ok(_) => {}
592:             }
593:             let line = String::from_utf8_lossy(&buf).trim().to_string();
594:             if let Some(u) = find_tunnel_url(&line) {
595:                 return Some(u);
596:             }
597:             if !line.is_empty() {
598:                 tail.push(line);
599:                 if tail.len() > 6 {
600:                     tail.remove(0);
601:                 }
602:             }
603:         }
604:     })
605:     .await;
606:     match found {
607:         Ok(Some(url)) => {
608:             // Sans lecteur, le tube se remplit et cloudflared finit par se bloquer.
609:             tauri::async_runtime::spawn(async move {
610:                 let mut buf = Vec::new();
611:                 loop {
612:                     buf.clear();
613:                     match rd.read_until(b'\n', &mut buf).await {
614:                         Ok(0) | Err(_) => break,
615:                         Ok(_) => {}
616:                     }
617:                 }
618:             });
619:             Ok((child, url))
620:         }
621:         Ok(None) => Err(format!(
622:             "cloudflared s'est arrêté avant d'ouvrir le tunnel : {}",
623:             tail.join(" | ")
624:         )),
625:         Err(_) => Err(format!(
626:             "cloudflared : pas d'URL de tunnel après {} s : {}",
627:             TUNNEL_WAIT.as_secs(),
628:             tail.join(" | ")
629:         )),
630:     }
631: }
