765: /// Crée (ou met à jour, si l'entrée `label` existe déjà) l'entrée pointant vers le tunnel.
766: /// Renvoie `(identifiant, réponse de FS tronquée)`.
767: async fn register(
768:     c: &Client,
769:     cfg: &BridgeConfig,
770:     url: &str,
771:     token: &str,
772: ) -> Result<(String, String), String> {
773:     let mut body = json!({
774:         "server_label": cfg.label,
775:         "server_url": format!("{url}/mcp?t={token}"),
776:         "server_description": "FS Code : pont local temporaire",
777:         "authorization": token,
778:         "enabled": true,
779:         // Outils visibles d'emblée par le modèle (pas de chargement à la demande).
780:         "defer_loading": false,
781:     });
782:     if let Some(o) = body.as_object_mut() {
783:         for (k, v) in &cfg.register_extra {
784:             o.insert(k.clone(), v.clone());
785:         }
786:     }
787: 
788:     let mut existing = find_entry(c, &cfg.label)
789:         .await
790:         .ok()
791:         .flatten()
792:         .and_then(|v| pick_id(&v));
793: 
794:     let mut last = String::new();
795:     for attempt in 0..3 {
796:         if attempt > 0 {
797:             // FS teste peut-être l'URL à l'enregistrement : le tunnel met parfois du temps à s'établir.
798:             sleep(Duration::from_secs(4)).await;
799:         }
800:         let res = match &existing {
801:             Some(id) => {
802:                 c.send_json("POST", &format!("/mcp/servers/{id}"), Some(body.clone()))
803:                     .await
804:             }
805:             None => {
806:                 c.send_json("POST", "/mcp/servers", Some(body.clone()))
807:                     .await
808:             }
809:         };
810:         match res {
811:             Ok(v) => {
812:                 let mut id = pick_id(&v).or_else(|| existing.clone());
813:                 if id.is_none() {
814:                     id = find_entry(c, &cfg.label)
815:                         .await
816:                         .ok()
817:                         .flatten()
818:                         .and_then(|e| pick_id(&e));
819:                 }
820:                 let id = id.ok_or("entrée créée, mais identifiant introuvable dans la réponse")?;
821:                 let names = tool_names(&v);
822:                 let mut note = format!("POST → {}", summarize(&v, token));
823:                 // `allowed_tools: []` est ambigu (tous ? aucun ?) : on liste alors explicitement les outils vus par FS.
824:                 let empty = v
825:                     .get("allowed_tools")
826:                     .and_then(Value::as_array)
827:                     .map(|a| a.is_empty())
828:                     .unwrap_or(false);
829:                 if empty && !names.is_empty() {
830:                     let mut upd = body.clone();
831:                     upd["allowed_tools"] = json!(names);
832:                     match c
833:                         .send_json("POST", &format!("/mcp/servers/{id}"), Some(upd))
834:                         .await
835:                     {
836:                         Ok(v2) => note.push_str(&format!(
837:                             "\nallowed_tools explicite ({} outils) → {}",
838:                             names.len(),
839:                             summarize(&v2, token)
840:                         )),
841:                         Err(e) => note.push_str(&format!("\nallowed_tools explicite refusé : {e}")),
842:                     }
843:                 }
844:                 return Ok((id, note));
845:             }
846:             Err(fs_api::Error::Status { status: 404, .. }) if existing.is_some() => {
847:                 existing = None; // l'entrée a disparu côté FS : on la recrée
848:                 last = "entrée introuvable (404), recréation".to_string();
849:             }
850:             Err(e) => last = e.to_string(),
851:         }
852:     }
853:     Err(format!("enregistrement chez France Student refusé : {last}"))
854: }
