884: /// Connecte les serveurs de `mcp.json` qui ne le sont pas déjà. Renvoie les avertissements.
885: async fn connect_all(app: &AppHandle, state: &State<'_, AppState>) -> Result<Vec<String>, String> {
886:     let cfg = mcp::load_config(&config_dir(app)?)?;
887:     let mut warnings = Vec::new();
888:     for (name, server) in &cfg {
889:         let up = state
890:             .mcp_up
891:             .lock()
892:             .map(|u| u.contains(name))
893:             .unwrap_or(false);
894:         if up {
895:             continue;
896:         }
897:         state.bridge.step(&format!("connexion de « {name} »"));
898:         match state.mcp.connect(name, server).await {
899:             Ok(_) => {
900:                 if let Ok(mut u) = state.mcp_up.lock() {
901:                     u.insert(name.clone());
902:                 }
903:             }
904:             Err(e) => warnings.push(format!("{name} : {e}")),
905:         }
906:     }
907:     Ok(warnings)
908: }
