910: async fn run_start(
911:     app: &AppHandle,
912:     state: &State<'_, AppState>,
913:     cfg: &BridgeConfig,
914:     live: &mut Live,
915: ) -> Result<(), String> {
916:     let b = &state.bridge;
917:     let c = crate::client(app, state).await?; // clé API requise
918: 
919:     let mut warnings = connect_all(app, state).await?;
920:     let exposed = state.mcp.exposed().await;
921:     if exposed.is_empty() {
922:         return Err("aucun outil MCP disponible : ajoute un serveur dans l'onglet MCP (mcp.json) et vérifie qu'il démarre.".to_string());
923:     }
924:     let n = exposed.len();
925:     let mut servers: Vec<String> = exposed.iter().map(|e| e.server.clone()).collect();
926:     servers.sort();
927:     servers.dedup();
928:     {
929:         let (s2, w2) = (servers.clone(), warnings.clone());
930:         b.set(|s| {
931:             s.tools = n;
932:             s.servers = s2;
933:             s.warnings = w2;
934:         });
935:     }
936: 
937:     b.step("serveur local");
938:     let token = new_token()?;
939:     let ctx = Ctx {
