943:     let (port, handle) = serve(ctx).await?;
944:     live.server = Some(handle);
945:     b.set(|s| s.port = Some(port));
946: 
947:     b.step("tunnel cloudflared");
948:     let (child, url) = start_tunnel(app, port).await?;
949:     live.tunnel = Some(child);
950:     {
951:         let u2 = url.clone();
