959:             REACH_WAIT.as_secs()
960:         ));
961:         let w2 = warnings.clone();
962:         b.set(|s| s.warnings = w2);
963:     }
964: 
965:     b.step("enregistrement chez France Student");
966:     let (id, note) = register(&c, cfg, &url, &token).await?;
967:     live.server_id = Some(id.clone());
968:     let extra = entry_note(&c, &cfg.label, &token).await;
969:     b.set(|s| {
970:         s.server_id = Some(id);
971:         s.register_note = Some(format!("{note}\n{extra}"));
972:         s.phase = Phase::Running;
973:         s.step = String::new();
974:     });
