88: fn b64url_decode(input: &str) -> Option<Vec<u8>> {
89:     let mut acc: u32 = 0;
90:     let mut bits: u8 = 0;
91:     let mut out = Vec::with_capacity(input.len() * 3 / 4);
92:     for b in input.bytes() {
93:         let v = match b {
94:             b'A'..=b'Z' => b - b'A',
95:             b'a'..=b'z' => b - b'a' + 26,
96:             b'0'..=b'9' => b - b'0' + 52,
97:             b'-' | b'+' => 62,
98:             b'_' | b'/' => 63,
99:             b'=' => break,
100:             _ => return None,
101:         };
102:         acc = (acc << 6) | (v as u32);
103:         bits += 6;
104:         if bits >= 8 {
105:             bits -= 8;
106:             out.push((acc >> bits) as u8);
107:         }
108:     }
109:     Some(out)
110: }
